def monotone_fill(g,seed,col,outline,bg=1):
 R=len(g);C=len(g[0]);out=[r[:] for r in g];sr,sc=seed
 # for each target, DP paths from seed with moves nonincreasing distance (taxicab) = steps toward target only
 for tr in range(R):
  for tc in range(C):
   if g[tr][tc]!=bg:continue
   # directions row and col toward target. dp over rectangle ordered by distance from seed
   dr=0 if tr==sr else (1 if tr>sr else -1);dc=0 if tc==sc else (1 if tc>sc else -1)
   cells=[(r,c) for r in range(min(sr,tr),max(sr,tr)+1) for c in range(min(sc,tc),max(sc,tc)+1)]
   cells.sort(key=lambda x:abs(x[0]-sr)+abs(x[1]-sc))
   reach={(sr,sc)}
   for r,c in cells:
    if (r,c)==(sr,sc) or g[r][c] not in (bg,col):continue
    if ((r-dr,c) in reach and dr) or ((r,c-dc) in reach and dc):reach.add((r,c))
   if (tr,tc) in reach:out[tr][tc]=col
 return out
